using System.ComponentModel;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

// --- Configuration ---------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = "gpt-4o-mini-2024-07-18";

// --- Tools -----------------------------------------------------------------
var notepad = new Notepad();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
            WebSearchAsync(query),
        name: "web_search",
        description: "Searches the web for the given query and returns a list of result snippets with titles and URLs."),

    AIFunctionFactory.Create(
        ([Description("Title or label for this note")] string title,
         [Description("Content of the note to save")] string content) =>
            notepad.SaveNote(title, content),
        name: "save_note",
        description: "Saves a research note for later reference. Use this to record key findings from web searches."),

    AIFunctionFactory.Create(
        () => notepad.GetAllNotes(),
        name: "get_notes",
        description: "Retrieves all previously saved research notes so they can be reviewed or summarized."),
};

// --- Agent setup -----------------------------------------------------------
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = chatClient.AsAIAgent(
    instructions: """
        You are a research agent. When the user provides a topic:
        1. Search the web for relevant information (perform 2-3 searches with different queries).
        2. Save key findings as notes using the save_note tool.
        3. Review your notes with get_notes.
        4. Produce a final summary that synthesizes all findings, citing sources where possible.
        Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run -------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (MAF)          ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 40));
Console.WriteLine();

var session = new ChatClientAgentSession();
var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions))
{
    Console.Write(update.Text);
}

Console.WriteLine();
Console.WriteLine();
Console.WriteLine(new string('─', 40));
Console.WriteLine($"Research complete. {notepad.Count} note(s) saved during research.");

// --- Web Search Tool -------------------------------------------------------
static async Task<string> WebSearchAsync(string query)
{
    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "ResearchAgent/1.0 (dotnet console app)");

    // Use DuckDuckGo Instant Answer API (no key required)
    var encodedQuery = Uri.EscapeDataString(query);
    var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

    try
    {
        var json = await http.GetFromJsonAsync<JsonElement>(url);
        var results = new StringBuilder();

        // Abstract / main answer
        var abstractText = json.GetProperty("Abstract").GetString();
        var abstractSource = json.GetProperty("AbstractSource").GetString();
        var abstractUrl = json.GetProperty("AbstractURL").GetString();

        if (!string.IsNullOrWhiteSpace(abstractText))
        {
            results.AppendLine($"## {abstractSource}");
            results.AppendLine(abstractText);
            results.AppendLine($"Source: {abstractUrl}");
            results.AppendLine();
        }

        // Related topics
        if (json.TryGetProperty("RelatedTopics", out var relatedTopics))
        {
            var count = 0;
            foreach (var topic in relatedTopics.EnumerateArray())
            {
                if (count >= 5) break;

                var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;

                if (!string.IsNullOrWhiteSpace(text))
                {
                    results.AppendLine($"- {text}");
                    if (!string.IsNullOrWhiteSpace(firstUrl))
                        results.AppendLine($"  URL: {firstUrl}");
                    count++;
                }
            }
        }

        var output = results.ToString();
        return string.IsNullOrWhiteSpace(output)
            ? $"No results found for '{query}'. Try a different search query."
            : output;
    }
    catch (Exception ex)
    {
        return $"Search failed for '{query}': {ex.Message}";
    }
}

// --- Notepad Tool ----------------------------------------------------------
sealed class Notepad
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public int Count => _notes.Count;

    public string SaveNote(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
        return $"Note '{title}' saved successfully (note #{_notes.Count}).";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var (title, content, timestamp) = _notes[i];
            sb.AppendLine($"### Note #{i + 1}: {title}");
            sb.AppendLine($"Saved at: {timestamp:u}");
            sb.AppendLine(content);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

